@sealed
class SessionImpl extends RustOpaque implements Session {
  // Not to be used by end users
  SessionImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  SessionImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_Session,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_Session,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_SessionPtr,
  );

  /// Detections to show (pre-selected ones and the review band) and the
  /// hidden ones below it.
  Future<Detected> detect({required String imagePath}) => RustLib.instance.api
      .crateApiSessionDetect(that: this, imagePath: imagePath);

  /// The model files' hashes, read from disk on first call. The app replaces
  /// the files only together with the session, so they match what was loaded.
  Future<ModelHashes> hashes() =>
      RustLib.instance.api.crateApiSessionHashes(that: this);

  ModelInfo info() => RustLib.instance.api.crateApiSessionInfo(that: this);

  /// Redacts `rects`, runs the export self-check and writes `out_path`
  /// (format from its extension, no metadata) if the check passes or
  /// `force` is set. `max_side` scales the written image down so its longer
  /// side is at most that many pixels; the check runs at full size.
  Future<ExportOutcome> redactAndExport({
    required String imagePath,
    required String outPath,
    required List<PixelRect> rects,
    required Fill fill,
    required bool force,
    int? maxSide,
  }) => RustLib.instance.api.crateApiSessionRedactAndExport(
    that: this,
    imagePath: imagePath,
    outPath: outPath,
    rects: rects,
    fill: fill,
    force: force,
    maxSide: maxSide,
  );

  /// Classes detected but not pre-selected, and skipped by the export check.
  void setOffClasses({required List<String> classes}) => RustLib.instance.api
      .crateApiSessionSetOffClasses(that: this, classes: classes);

  /// Scales every class's thresholds: low pre-selects more, high less.
  void setThreshold({required ThresholdPreset preset}) => RustLib.instance.api
      .crateApiSessionSetThreshold(that: this, preset: preset);
}

@sealed
class VideoProjectImpl extends RustOpaque implements VideoProject {
  // Not to be used by end users
  VideoProjectImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  VideoProjectImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_VideoProject,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_VideoProject,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_VideoProjectPtr,
  );

  /// Adds a track for a region the user drew on `frame`, followed across
  /// keyframes by template matching. Returns its index in the summary.
  Future<int> addManual({required int frame, required PixelRect rect}) =>
      RustLib.instance.api.crateApiVideoProjectAddManual(
        that: this,
        frame: frame,
        rect: rect,
      );

  /// Decodes the video, detects on keyframes and links tracks; reports
  /// frames decoded to `progress`.
  Stream<int> analyze({required Session session}) => RustLib.instance.api
      .crateApiVideoProjectAnalyze(that: this, session: session);

  /// Every track's box in `frame`.
  List<TrackBox> boxesAt({required int frame}) => RustLib.instance.api
      .crateApiVideoProjectBoxesAt(that: this, frame: frame);

  /// Redacts the chosen tracks in every frame and writes an H.264 MP4.
  /// The export self-check runs on each keyframe; on the first failure
  /// the export stops and writes nothing, unless forced.
  Stream<ExportProgress> export_({
    required Session session,
    required String outPath,
    required VideoExportOptions opts,
  }) => RustLib.instance.api.crateApiVideoProjectExport(
    that: this,
    session: session,
    outPath: outPath,
    opts: opts,
  );

  /// The image showing `frame`: the JPEG of the last keyframe at or before it.
  String previewPath({required int frame}) => RustLib.instance.api
      .crateApiVideoProjectPreviewPath(that: this, frame: frame);

  VideoSummary summary() =>
      RustLib.instance.api.crateApiVideoProjectSummary(that: this);
}
